learn=[('Choose automatic or explicit invocation', 'Compare an unnamed specialist request with a prompt that names security-reviewer. Description matching is model behavior; inspect actual Agent calls to confirm selection.'), ('Build definitions at runtime', 'A typed factory changes the reviewer prompt and model: balanced uses Sonnet, strict uses Opus. Both keep the same read-only tools; stronger models do not guarantee better results.'), ('Trace parent and child identities', 'Distinguish the parent session_id, Agent tool-use ID, parent_tool_use_id and child agent_id. Display actual nested calls and lifecycle reports.'), ('Resume actual child history', 'Run discovery, capture the parent session and child ID, then query again with the same definitions and resume option. SendMessage targets that existing child; prove its ID stays stable.'), ('Use the smallest tool set', 'A reviewer can read and search. The test runner can run one exact Node test command. Independent fixture hashes confirm no edits.'), ('Troubleshoot missing delegation and collisions', 'Sharpen descriptions or name a specialist explicitly. Inspect a real same-name filesystem definition overridden by the programmatic agents option. New agents directories require a fresh session.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3144\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and Sonnet/Opus model access. Install Git Bash on Windows if the SDK requires it. No GitHub token or managed-agent IDs are needed.', 'node --version\nnpm --version'), ('Install and configure .env', 'Install locked dependencies. Preserve an existing .env file and enter your own API key privately. Shell variables take precedence over the file.', 'cd .\\agent-sdk\\lesson44-invoking-subagents\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the server terminal open. Use all five student pages. If the port is occupied, the app prints an actionable message; update PORT and restart as needed.', 'npm start\n# http://127.0.0.1:3144'), ('Compare invocation and factories', 'Automatic does not name a specialist in its task. Explicit does. Balanced and Strict build different prompt/model definitions at runtime, with identical read-only tools.', 'npm run sample:env -- automatic\nnpm run sample:env -- explicit\nnpm run sample:env -- balanced\nnpm run sample:env -- strict'), ('Trace and resume a child', 'Detect shows native Agent tool IDs and correlated child messages. Resume performs two parent queries with the same definitions and session, then sends the existing child a follow-up. Inspect stable agent_id and the absence of file reads during follow-up.', 'npm run sample:env -- detect\nnpm run sample:env -- resume'), ('Compare tool sets and precedence', 'Readonly permits analysis only. Tests executes a fixed real assertion suite with its intentional failure. Precedence verifies a programmatic reviewer overrides a same-name filesystem agent. All temporary fixtures and transcripts are removed after collection.', 'npm run sample:env -- readonly\nnpm run sample:env -- tests\nnpm run sample:env -- precedence\nnpm test')]
specs=[('Choose automatic or explicit invocation', 'src/agent.ts', 'automatic:', 'The automatic task asks for description-based selection without naming a specialist. The explicit task names security-reviewer. Both require actual delegation evidence.', 0, 1, 5), ('Build a runtime reviewer definition', 'src/agents.ts', 'export function createSecurityAgent', 'The typed factory selects a balanced or strict prompt at request time. Description tells the parent when to select the specialist.', 1, 3, 7), ('Select model and tools independently', 'src/agents.ts', 'tools: [', 'Sonnet and Opus are runtime model aliases. Both reviewers retain the same read-only tools and bounded turns.', 1, 3, 5), ('Attach the same agents to each query', 'src/agent.ts', 'agents: agentDefinitions,', 'Attach stable definitions to the parent query. Enable Agent for initial delegation and SendMessage for current-runtime continuation.', 1, 2, 6), ('Detect the native Agent invocation', 'src/agent.ts', 'if (!parentId && (b.name === "Agent"', 'Retain the actual Agent tool-use ID and input. Match Task as well for compatibility with older emitted names.', 1, 2, 5), ('Correlate nested messages with child IDs', 'src/agent.ts', 'observe("child-correlation"', 'Child messages expose parent_tool_use_id and agent_id. These identify a delegation and child; neither is the parent session ID.', 3, 0, 5), ('Extract the child ID from native returns', 'src/agent.ts', 'export function extractAgentId', 'Parse the agentId trailer in actual returned message content. Do not substitute a tool-use ID or invent a resumable child.', 3, 1, 3), ('Require captured IDs before follow-up', 'src/agent.ts', 'if (c.mode === "resume")', 'Require both native parent session and child ID. Keep the same definitions and record the exact resume request.', 0, 1, 7), ('Resume the owning parent session', 'src/agent.ts', 'agents: agentDefinitions,', 'The second query receives resume with the captured parent session ID and reuses the agent definitions. The parent session selects the stored conversation.', 1, 2, 4), ('Target the existing child with SendMessage', 'src/policy.ts', 'if (name === "SendMessage")', 'Current runtime continuation uses SendMessage to the exact captured child ID. Reject unrelated recipients; a fresh Agent call is blocked during follow-up.', 2, 3, 3), ('Capture the native completion report', 'src/agent.ts', 'if (i.hook_event_name === "SubagentStop")', 'Record actual child stop events and final report. Consume the entire parent stream because resumed work can complete asynchronously.', 3, 1, 8), ('Create a same-name filesystem definition', 'src/workspace.ts', 'join(cwd, ".claude", "agents", "security-reviewer.md")', 'The project contains a same-name file agent with a different marker-only prompt. The programmatic definition takes precedence; verify actual review activity.', 1, 4, 2), ('Independently verify file integrity', 'src/agent.ts', 'fixtureUnchanged: before.hash === after.hash', 'Hash the toy source, tests and endpoint fixture after the workflow. Native reports and unchanged files are independent evidence.', 1, 4, 5)]
document('/','Invoke and <em>control specialists.</em>','Choose the right specialist, trace native activity and resume its history.','<div class="flow"><div><b>01 · Select</b><p>Description or explicit name</p></div><span>→</span><div><b>02 · Configure</b><p>Runtime factory and scoped tools</p></div><span>→</span><div><b>03 · Continue</b><p>Native IDs and child resume</p></div></div><section class="panel" id="controls"><h2>Invoke and control subagents</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Subagent experiment</label><select id="mode"><option value="automatic">Automatic · match a specialist description</option><option value="explicit">Explicit · name security-reviewer</option><option value="balanced">Dynamic factory · balanced Sonnet review</option><option value="strict">Dynamic factory · strict Opus review</option><option value="detect">Detect · nested endpoint-finder activity</option><option value="resume">Resume · same child history and ID</option><option value="readonly">Tool scope · read-only security reviewer</option><option value="tests">Tool scope · real test-runner command</option><option value="precedence">Name collision · programmatic definition wins</option></select><button id="run" class="primary" disabled>Run subagent experiment →</button><p class="meta">Actual SDK calls with a $0.60 estimated threshold per parent query. Strict uses the Opus alias and requires model access. Resume makes two parent queries and continues the same child through SendMessage. The toy auth fixture intentionally fails one assertion; no files are edited.</p></section><section class="step" id="picker-panel"><h2>Inspect an actual delegation</h2><p id="choice-status" class="note">Choose an Agent tool-use ID to inspect its correlated host-side child telemetry.</p><label for="session-picker">Actual Agent tool-use IDs</label><select id="session-picker"><option>No delegations yet</option></select><button id="resume-session" style="display:none!important" hidden disabled>Resume selected session</button></section><section class="step" id="specialists-panel"><h2>Actual specialist activity</h2><div class="grid" id="specialists"></div><p>Native SubagentStart and SubagentStop events drive these cards. Host telemetry is separate from the parent model’s context.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Host configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Each query and its actual agent definitions, tools and model options appear in the observation selector.</p></section></div><section class="step" id="comparison-panel"><h2>Actual parent responses</h2><div class="grid" id="branch-cards"></div></section><section class="step" id="results-panel"><h2>Actual results and parent session IDs</h2><div class="table"><table><thead><tr><th>Query</th><th>Stage</th><th>Status</th><th>session_id</th><th>Result text</th></tr></thead><tbody id="result-history"></tbody></table></div><pre class="json-view"><code id="latest-result" class="language-json">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Actual delegation catalog</h2><pre class="json-view"><code id="catalog" class="language-json">[]</code></pre></section><section class="step" id="messages-panel"><h2>Correlated child tools and reports</h2><pre class="json-view"><code id="messages" class="language-json">{}</code></pre><p>These are actual child messages forwarded to the host with parent_tool_use_id, not a claim that all child tool results enter the parent model context.</p></section><section class="step" id="storage-panel"><h2>Definitions, child IDs, reports and resume evidence</h2><pre class="json-view"><code id="storage" class="language-json">{}</code></pre><p>Inspect actual definitions, delegation inputs, child tools, reports, lifecycle times and observed model IDs. The fixture hash must remain unchanged.</p></section><section class="step" id="observation-panel"><h2>Inspect actual parent and specialist events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand invocation, runtime factories, stable child IDs and history.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. All experiments finish automatically. Inspect an Agent tool-use ID without sending another model prompt. Consume the entire query stream: asynchronous child completions can produce multiple native parent result frames. Change PORT if 3144 is occupied.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','Agent tool','Specialists','Classroom files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 44 · Select → configure → detect → resume</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The diagram groups programmatic definitions, actual Agent tool calls, specialist loops and returned reports. Resume uses the same parent session and captured child ID; current runtime continuations use SendMessage rather than a new Agent invocation. Numbered steps group teaching scenarios rather than one universal sequence.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked session workflow steps"></div>'+walk)

reference=[('Version detail: current child resume', 'The attached lesson uses an older Agent resume description. In the pinned current runtime, resume the parent query with options.resume and continue its child through SendMessage({to: agentId, message}). A new Agent invocation creates a new instance. Verify stable child IDs instead of assuming a successful parent answer proves resume.'), ('Four identifiers', 'session_id belongs to the parent conversation. The Agent tool-use ID identifies a delegation. parent_tool_use_id links nested messages to that delegation. agent_id identifies the actual child and remains stable across a real continuation.'), ('Automatic versus explicit', 'The automatic task does not name a specialist but asks the parent to choose by description. The explicit task names security-reviewer. Delegation is observed model behavior; the app does not implement a fake router or guarantee identical selections on every model.'), ('Runtime factory and model access', 'Balanced uses the sonnet alias; strict uses opus. Both have Read/Grep/Glob and no editing or shell capability. Inspect actual model IDs. Aliases and account availability vary; this is an educational comparison, not a controlled quality or cost benchmark.'), ('Child history proof', 'Resume discovers three routes, then asks the same child about /orders/:id without additional reads. The follow-up guard rejects new Agent calls and file tools. Evidence must show the same agent_id, the original parent session and a SendMessage addressed to that child.'), ('Tool scope and troubleshooting', 'Review tools are read-only. The test runner may execute only node --test auth.test.cjs. Programmatic definitions override same-name project agents. New .claude/agents directories need session restart; verify YAML and unique names when agents do not load.'), ('Partial output and lifetime', 'A child maxTurns limit can produce a partial report; that is not equivalent to completed work. Custom or general-purpose agents support continuation; Explore and Plan are one-shot. This lab bounds turns and removes all temporary transcripts after the experiment, so its captured IDs are explanatory evidence, not a permanent external resume API.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 44 · Invoking and controlling subagents\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson44-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson44-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson44-invoking-subagents`. Open http://127.0.0.1:3144 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK subagents documentation](https://code.claude.com/docs/en/agent-sdk/subagents)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for specialist definitions, bounded delegation, scoped tools, actual fixture behavior and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 44 pages and thirteen source-linked UML steps.')

(PUBLIC/"style.css").write_text((PUBLIC/"style.css").read_text(encoding="utf-8")+'\n#conversation{max-height:540px;overflow:auto}.markdown-body{font-size:22px;line-height:1.6}.markdown-body article,#conversation article{padding:16px;border-bottom:1px solid var(--line)}.json-view{max-height:380px}#result-history td{max-width:380px;overflow-wrap:anywhere}.table{max-height:350px;overflow:auto}#branch-cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr))}#branch-cards .branch-card{padding:20px;overflow-wrap:anywhere}#branch-cards .meta{font-size:20px}#session-picker{font-size:21px}#picker-panel .meta{margin-bottom:0}\n',encoding="utf-8")
